-- kairos:no-transaction
-- match_below_bar (WP-42; database-60, matching-55; 02-database 7.2.7): the server-only match status for a scored pair under
-- the user's bar, kept so it is never paid for twice (WP-23 writes it). Generated by drizzle-kit into 0009 and moved here
-- by hand with IF NOT EXISTS added: ADD VALUE needs a file of its own, and a new value is usable only once committed.
ALTER TYPE "public"."match_status" ADD VALUE IF NOT EXISTS 'below_bar';
